package com.example.mareasv7.data
import retrofit2.Retrofit; import retrofit2.converter.gson.GsonConverterFactory; import retrofit2.http.GET; import retrofit2.http.Query
interface Ihm { @GET("api-ihm/getmarea") suspend fun stations(@Query("request")r:String="getlist",@Query("format")f:String="json"):StationEnvelope; @GET("api-ihm/getmarea") suspend fun tides(@Query("request")r:String="gettide",@Query("id")id:String,@Query("format")f:String="json",@Query("date")date:String):IhmResponse }
interface Weather { @GET("v1/forecast") suspend fun get(@Query("latitude")lat:Double,@Query("longitude")lon:Double,@Query("current")current:String="temperature_2m,apparent_temperature,relative_humidity_2m,surface_pressure,uv_index,wind_speed_10m,wind_direction_10m,wind_gusts_10m",@Query("hourly")hourly:String="temperature_2m,uv_index,wind_speed_10m,wind_gusts_10m",@Query("forecast_days")days:Int=2,@Query("timezone")tz:String="Europe/Madrid"):WeatherResponse }
interface Marine { @GET("v1/marine") suspend fun get(@Query("latitude")lat:Double,@Query("longitude")lon:Double,@Query("current")current:String="wave_height,wave_period,wave_direction,swell_wave_height,sea_surface_temperature",@Query("timezone")tz:String="Europe/Madrid"):MarineResponse }
object Api { private fun r(u:String)=Retrofit.Builder().baseUrl(u).addConverterFactory(GsonConverterFactory.create()).build(); val ihm=r("https://ideihm.covam.es/").create(Ihm::class.java); val weather=r("https://api.open-meteo.com/").create(Weather::class.java); val marine=r("https://marine-api.open-meteo.com/").create(Marine::class.java) }
